// Load the Haifa trip with the day ending 20:30; list drafted shows past it. argv: festival dayEndMin
const R = "/home/claude/EdFringeNow/product/requirements";
const { newPage, closeBrowser, ORIGIN } = require(R + "/shared/harness/browser");
const { plannerReady } = require(R + "/shared/case-helpers");
(async () => {
  const fest = process.argv[2] || "haifa-iff", end = Number(process.argv[3] || 1230);
  const { page, context } = await newPage({ viewport: "desktop", localStorage: { "planNG.prefs": JSON.stringify({ dayEndMin: end }) } });
  await page.goto(`${ORIGIN}/planNG/?festival=${fest}`, { waitUntil: "load" });
  await plannerReady(page, fest);
  const rows = await page.evaluate(() => [...document.querySelectorAll(".sch-show")].map((b) => ({ key: b.dataset.key, slug: b.dataset.slug, time: b.querySelector(".sch-time")?.textContent })));
  console.log(rows.map((r) => r.key + " " + r.time + " " + r.slug).join("\n"));
  await context.close(); await closeBrowser();
})();

