"use strict";
const { jerusalemAllDays, jerusalemReady, jerusalemStarred, settle } = require("../../shared/case-helpers");

// A show with more than one night, so the nights list has something to say and
// the rarity pill reads "1 of 3" rather than "only night".
const FAVOURITE = '.sch-day[data-date="2026-10-19"] .sch-show.sch-show--fav';

module.exports = {
  description: "hovering a card opens how rare the show is, every night it plays, and the four verdicts",
  page: "/planNG/?festival=jerusalem-comedy",
  viewport: "desktop",
  localStorage: { ...jerusalemStarred(["yolo"]), ...jerusalemAllDays() },
  ready: jerusalemReady,
  async capture(page, t) {
    await page.hover(FAVOURITE);
    await settle(page);
    return t.unionClip([FAVOURITE, "#calPreview"], 8);
  },
};
1230:- `20.4` Hovering a card opens everything about it: how rare the show is, every night it plays, and the four verdicts.
1231-
1232-  ![jerusalem-preview.20.4](requirements/screen/cases/jerusalem-preview.20.4.png) <!-- req-gallery:20.4 -->
1233-
1234-  <details><summary>Notes</summary>
1235-
1236-  One popup, because these are one thought: how few nights the show has is the
1237-  reason it holds the hour, its other nights are what "not this night" would
1238-  fall back on, and the four buttons are the answers. Nothing here is on the
1239-  card's own face. The popup is reached by pointer and by keyboard alike, and
1240-  stays open while the pointer travels into it, because it is something to act
1241-  on rather than something to read.
1242-  </details>
1243-
1244-- `20.5` A locked card is marked as locked, and its hour stops offering anyone else.

