  padding: 4px 6px; min-width: 0;
  font: inherit; font-size: 0.62rem; text-align: start;
  border: 1px solid var(--line); border-radius: 7px;
  background: var(--paper); color: var(--ink); cursor: pointer;
}
.vb-mark { flex: 0 0 auto; font-size: 0.68rem; line-height: 1; }
.vb-word { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.vb:hover { border-color: var(--violet); }
.vb:focus-visible { outline: 2px solid var(--violet); outline-offset: 1px; }
.vb.is-on { border-color: var(--ok); background: color-mix(in srgb, var(--ok) 16%, var(--paper)); }
