const R = "/home/claude/EdFringeNow/product/requirements";
const { newPage, closeBrowser, ORIGIN } = require(R + "/shared/harness/browser");
const { plannerReady } = require(R + "/shared/case-helpers");
(async () => {
  const [fest, w, out] = [process.argv[2], Number(process.argv[3]), process.argv[4]];
  const { page, context } = await newPage({ viewport: "desktop" });
  await page.setViewportSize({ width: w, height: 900 });
  await page.goto(`${ORIGIN}/planNG/?festival=${fest}`, { waitUntil: "load" });
  await plannerReady(page, fest);
  const m = await page.evaluate(() => {
    const wrap = document.querySelector("#scheduleWrap"), sch = document.querySelector("#schedule");
    const days = [...document.querySelectorAll("#schedule .sch-day")];
    return { wrap: [wrap.clientWidth, wrap.scrollWidth], sch: [sch.clientWidth, sch.scrollWidth], doc: [document.documentElement.clientWidth, document.documentElement.scrollWidth], days: days.length, dayW: days.map((d) => Math.round(d.getBoundingClientRect().width)).slice(0, 4), cls: sch.className };
  });
  console.log(fest, w, JSON.stringify(m));
  if (out) await page.screenshot({ path: out, fullPage: true });
  await context.close(); await closeBrowser();
})();
EOF
