"use strict";
const { plannerReady } = require("../../shared/case-helpers");

const MAX_DAY_PX = 280;
const TRIPS = ["haifa-iff", "jerusalem-comedy"];
const WIDTHS = [390, 1280, 2560];

module.exports = {
  description: "the calendar never scrolls sideways, and no day is wider than 280px",
  page: "/planNG/?festival=jerusalem-comedy",
  viewport: "desktop",
  async verify(page, { origin, assert }) {
    for (const festival of TRIPS) {
      for (const width of WIDTHS) {
        await page.setViewportSize({ width, height: 900 });
        await page.goto(`${origin}/planNG/?festival=${festival}`, { waitUntil: "load" });
        await plannerReady(page, festival);
        const m = await page.evaluate(() => {
          const wrap = document.querySelector("#scheduleWrap");
          return {
            wrap: [wrap.scrollWidth, wrap.clientWidth],
            page: [document.documentElement.scrollWidth, document.documentElement.clientWidth],
            widest: Math.max(...[...document.querySelectorAll("#schedule .sch-day")].map((d) => d.getBoundingClientRect().width)),
          };
        });
        const at = `${festival} at ${width}px`;
        assert.ok(m.wrap[0] <= m.wrap[1], `${at}: the calendar scrolls sideways (${m.wrap[0]} > ${m.wrap[1]})`);
        assert.ok(m.page[0] <= m.page[1], `${at}: the page scrolls sideways (${m.page[0]} > ${m.page[1]})`);
        assert.ok(m.widest <= MAX_DAY_PX, `${at}: a day is ${m.widest}px wide`);
      }
    }
  },
};
EOF
