  ![jerusalem-flight-days.28.5](requirements/screen/cases/jerusalem-flight-days.28.5.png) <!-- req-gallery:28.5 -->

  <details><summary>Notes</summary>

  Coming from London, with the fare service answering from its fixture: the
  cheapest flight out and home (section 27) bound the calendar's first and
  last day, and nothing is drafted under either block. A reader who needs no
  flight has whole days at both ends.
  </details>

- `28.6` A flight's block runs to its landing plus the trip from the airport, or from its departure less the time the airport asks for.
"use strict";
const { calendarDays, jerusalemReady, routeFares, flightsSettled } = require("../../shared/case-helpers");

/* Coming from London: the trip's first day beside its last, each with the
 * hours its flight takes. */
module.exports = {
  description: "flying in takes the first day until landing and the trip from the airport; flying home takes the last from when you leave for it",
  page: "/planNG/?festival=jerusalem-comedy",
  viewport: "desktop",
  ready: jerusalemReady,
  async drive(page) {
    await routeFares(page);
    await page.click('.flight--out [data-origin="ask"]');
    await page.selectOption("#originCountry", "GB");
    await flightsSettled(page);
    await page.waitForFunction(() => document.querySelectorAll(".sch-own--flight").length === 2, null, { timeout: 20000 });
    await jerusalemReady(page);
  },
  async capture(page, t) {
    const days = await calendarDays(page);
    const day = async (iso) => t.clip(t.pad(await t.rectOf(`.sch-day[data-date="${iso}"]`), 2));
    return t.stitchH([await day(days[0]), await day(days[days.length - 1])]);
  },
};

