"use strict";
const { plannerReady } = require("../../shared/case-helpers");

/* The Haifa trip opens with a sliver either side of the festival. Dragging the
 * day's end up by pointer, every day keeps the width it had when the drag
 * began, the slivers included, until the line is let go. */
const widths = (page) =>
  page.$$eval("#schedule .sch-day", (cols) => cols.map((c) => [c.dataset.date, Math.round(c.getBoundingClientRect().width)]));

module.exports = {
  description: "dragging the day's start or end holds every day at its width",
  page: "/planNG/?festival=haifa-iff",
  viewport: "desktop",
  async verify(page, { origin, assert }) {
    await page.goto(`${origin}/planNG/?festival=haifa-iff`, { waitUntil: "load" });
    await plannerReady(page, "haifa-iff");
    const before = await widths(page);
    assert.ok(
      before.some(([, w]) => w < 40),
      "the trip opens with a sliver for a day with nothing on it"
    );

    for (const which of ["end", "start"]) {
      const line = await page.locator(`.sch-dayline--${which} .sch-dayline-grip, .sch-dayline--${which}`).first().boundingBox();
      const x = line.x + line.width / 2;
      const y = line.y + line.height / 2;
      await page.mouse.move(x, y);
      await page.mouse.down();
      const step = which === "end" ? -30 : 30;
      for (let i = 1; i <= 8; i++) {
        await page.mouse.move(x, y + step * i);
        assert.deepEqual(await widths(page), before, `every day keeps its width while the day's ${which} is dragged`);
      }
      await page.mouse.up();
    }
  },
};
EOF
cat > $C/behavior/cases/planng-motion.21.17.case.js <<'EOF'
"use strict";
const { plannerReady } = require("../../shared/case-helpers");

/* The harness lands every animation on its end state at once; this wraps that
 * stub to record what the calendar asked to animate, and on which block. The
 * day's end is moved earlier (shows leave) and back (shows come back). */
const RECORD = `
  window.__motion = [];
  const landed = Element.prototype.animate;
  Element.prototype.animate = function (keyframes, options) {
    if (this.closest && this.closest("#scheduleWrap")) {
      const first = Array.isArray(keyframes) ? keyframes[0] : keyframes;
      window.__motion.push({
        what: this.classList.contains("sch-ghost") ? "leave" : this.classList.contains("sch-day") ? "width" : "block",
        from: JSON.stringify(first),
      });
    }
    return landed.call(this, keyframes, options);
  };
`;

async function moveDayEnd(page) {
  const line = page.locator(".sch-dayline--end");
  await line.focus();
  await page.evaluate(() => (window.__motion = []));
  for (let i = 0; i < 12; i++) await page.keyboard.press("ArrowUp");
  const out = await page.evaluate(() => window.__motion);
  await page.evaluate(() => (window.__motion = []));
  for (let i = 0; i < 12; i++) await page.keyboard.press("ArrowDown");
  const back = await page.evaluate(() => window.__motion);
  return { out, back };
}

module.exports = {
  description: "shows the calendar gains or loses fade in or out, and the ones that move slide",
  page: "/planNG/?festival=haifa-iff",
  viewport: "desktop",
  async verify(page, { origin, assert }) {
    await page.addInitScript(RECORD);
    await page.goto(`${origin}/planNG/?festival=haifa-iff`, { waitUntil: "load" });
    await plannerReady(page, "haifa-iff");
    const { out, back } = await moveDayEnd(page);
    assert.ok(
      out.some((m) => m.what === "leave" && /"opacity":1/.test(m.from)),
      "a show the earlier day's end drops is drawn where it stood and fades away"
    );
    assert.ok(
      back.some((m) => m.what === "block" && /"opacity":0/.test(m.from)),
      "a show the later day's end brings back grows in from nothing"
    );
    assert.ok(
      [...out, ...back].some((m) => m.what === "block" && /translate/.test(m.from)),
      "a show that moves slides from where it was"
    );

    await page.emulateMedia({ reducedMotion: "reduce" });
    await page.reload({ waitUntil: "load" });
    await plannerReady(page, "haifa-iff");
    const still = await moveDayEnd(page);
    assert.deepEqual([...still.out, ...still.back], [], "asked for reduced motion, nothing on the calendar moves");
  },
};
EOF
cat > $C/behavior/cases/planng-pace-any.21.18.case.js <<'EOF'
"use strict";
const { plannerReady } = require("../../shared/case-helpers");

/* "How full a day" typed past the old top of eight, then down to nothing. */
const stored = (page) => page.evaluate(() => JSON.parse(localStorage.getItem("planNG.prefs") || "{}").maxPerDay);

async function setPerDay(page, n) {
  const input = page.locator("[data-num='maxPerDay']");
  await input.fill(String(n));
  await input.dispatchEvent("change");
}

module.exports = {
  description: "how full a day takes any whole number of shows from zero up",
  page: "/planNG/?festival=haifa-iff",
  viewport: "desktop",
  async verify(page, { origin, assert }) {
    await page.goto(`${origin}/planNG/?festival=haifa-iff`, { waitUntil: "load" });
    await plannerReady(page, "haifa-iff");
    await page.click("[data-open='pace']");
    const input = page.locator("[data-num='maxPerDay']");
    assert.equal(await input.getAttribute("min"), "0", "the count starts at zero");
    assert.equal(await input.getAttribute("max"), null, "and has no top");

    await setPerDay(page, 12);
    assert.equal(await stored(page), 12, "twelve a day is kept as twelve");

    await setPerDay(page, 0);
    assert.equal(await stored(page), 0, "none a day is kept as none");
    assert.equal(await page.locator("#schedule .sch-show").count(), 0, "and drafts no shows");

    await page.reload({ waitUntil: "load" });
    await plannerReady(page, "haifa-iff");
    await page.click("[data-open='pace']");
    assert.equal(await page.locator("[data-num='maxPerDay']").inputValue(), "0", "none survives a reload");
  },
};
EOF
