// The behavior kind's runner: each case drives a real page in the harness and
// asserts the gesture's consequence in code — the coded assertions ARE the
// owner-approved expected, so they are never weakened to pass. Runs in the
// `test:ui` lane. Self-asserts that it covers exactly the behavior cases.
"use strict";

const { test, describe, after } = require("node:test");
const assert = require("node:assert/strict");
const { loadCases } = require("../shared/cases");
const { newPage, closeBrowser, ORIGIN } = require("../shared/harness/browser");
const { CASE_CONCURRENCY } = require("../shared/case-concurrency");

const CASES = loadCases().filter((c) => c.kind === "behavior");

test("there is at least one behavior case", () => {
  assert.ok(CASES.length > 0, "no behavior cases found");
});

test("every behavior case declares a verify()", () => {
  const bad = CASES.filter((c) => typeof c.verify !== "function").map((c) => c.name);
  assert.deepEqual(bad, [], "behavior cases without a verify():");
});

describe("behavior cases", { concurrency: CASE_CONCURRENCY }, () => {
  for (const testCase of CASES) {
    test(`behavior "${testCase.name}" (${testCase.description})`, async () => {
      const { page, context } = await newPage({
        viewport: testCase.viewport,
        localStorage: testCase.localStorage,
        geolocation: testCase.geolocation,
        failData: testCase.failData,
        colorScheme: testCase.colorScheme,
      });
      try {
        await testCase.verify(page, { origin: ORIGIN, context, assert });
      } finally {
        await context.close();
      }
    });
  }
// The refresh lane: regenerates EVERY screen golden and the requirements-doc
// gallery together, so they cannot skew. Running it is how an intended UI
// change lands — the refreshed PNGs ride the diff for the owner to approve.
// It is NEVER how a red case gets fixed: on an unexpected mismatch the
// re-baselining procedure applies (surface actual/expected/diff, ask the
// owner, refresh only on approval).
//
//   node product/requirements/shared/refresh.js [name-filter]
"use strict";

const fs = require("node:fs");
const { loadCases, goldenPath } = require("./cases");
const { renderScreenCase } = require("./render-case");
const { closeBrowser } = require("./harness/browser");
const { buildGallery, DOC_PATH } = require("./gallery");
const { CASE_CONCURRENCY } = require("./case-concurrency");

(async () => {
  const filter = process.argv[2] || "";
  const cases = loadCases().filter((c) => c.kind === "screen" && c.name.includes(filter));
  // Rendered by the same pool as the comparing lane — a golden a case renders
  // alongside others has to be the one that lane will compare it against.
  const queue = [...cases];
  await Promise.all(
    Array.from({ length: CASE_CONCURRENCY }, async () => {
      for (let testCase = queue.shift(); testCase; testCase = queue.shift()) {
        const out = goldenPath(testCase);
        fs.writeFileSync(out, await renderScreenCase(testCase));
        console.log(`wrote ${out}`);
      }
    })
  );
  await closeBrowser();
  fs.writeFileSync(DOC_PATH, buildGallery());
  console.log(`refreshed gallery in ${DOC_PATH}`);
})().catch((err) => {
  console.error(err);
  process.exit(1);
});

