python3 - <<'EOF'
p='site/planNG/planNG.js'
s=open(p).read()
old=s[s.index("  let text;\n  let title;\n  let key;\n  if (a.venueCode"):s.index("  leg.dataset.i18nSlot = key;")]
new='''  // The leg's face is a glance (minutes, distance, time to spare); the card it
  // opens on a rest of the pointer says the same in a sentence.
  const venue = (slot) => foreign(slot.venueName || "", slot.slug);
  let text;
  let key;
  let card;
  let spoken;
  if (a.venueCode && b.venueCode && a.venueCode === b.venueCode) {
    key = "leg.sameVenue";
    text = t(key, { gap: gapMin });
    card = tHtml("leg.card.same", { gap: gapMin }, { venue: venue(a) });
    spoken = t("leg.card.same", { gap: gapMin, venue: a.venueName || "" });
  } else {
    const km = distanceKm({ lat: a.venueLat, lng: a.venueLng }, { lat: b.venueLat, lng: b.venueLng });
    const mins = travelMinutes(
      { lat: a.venueLat, lng: a.venueLng },
      { lat: b.venueLat, lng: b.venueLng },
      state.mode
    );
    if (km == null || mins == null) {
      key = "leg.nearby";
      text = t(key, { gap: gapMin });
      card = escapeHtml(t("leg.card.unknown"));
      spoken = t("leg.card.unknown");
    } else {
      const spare = Math.round(gapMin - mins);
      key = "leg.travel";
      text = t(key, {
        minutes: Math.round(mins),
        km: km1(km),
        spare: `${spare >= 0 ? "+" : ""}${spare}`,
      });
      const trip = { minutes: Math.round(mins) };
      const margin = spare >= 0 ? t("leg.card.spare", { km: km1(km), spare }) : t("leg.card.late", { km: km1(km), late: -spare });
      card =
        `<span class="leg-card-trip">${tHtml(meta.cardKey, trip, { from: venue(a), to: venue(b) })}</span>` +
        `<span class="leg-card-margin">${escapeHtml(margin)}</span>`;
      spoken = `${t(meta.cardKey, { ...trip, from: a.venueName || "", to: b.venueName || "" })} ${margin}`;
    }
  }
  leg.dataset.card = `<span class="leg-card-emoji" aria-hidden="true">${meta.emoji}</span><span class="leg-card-words">${card}</span>`;
  leg.setAttribute("aria-label", spoken);
'''
s=s.replace(old,new)
s=s.replace('  leg.title = title;\n','')
s=s.replace('tipKey: "travel.walk.tip", verbKey: "travel.mode.walk" }','tipKey: "travel.walk.tip", cardKey: "leg.card.walk" }')
s=s.replace('tipKey: "travel.bike.tip", verbKey: "travel.mode.bike" }','tipKey: "travel.bike.tip", cardKey: "leg.card.bike" }')
s=s.replace('tipKey: "travel.car.tip", verbKey: "travel.mode.car" }','tipKey: "travel.car.tip", cardKey: "leg.card.car" }')
open(p,'w').write(s)
EOF
